-- Deities and Demigods: Olympian pantheon divine stat blocks, batch A.
-- Source: Deities and Demigods (2002), Chapter 4, pp. 101-108.
-- Printed 3.0 statistics are preserved, with official 3.5 revision deltas recorded separately in mechanics JSON.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Fist filled with lightning bolts' WHERE source_id='dd-3.0' AND slug='zeus' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Seashell' WHERE source_id='dd-3.0' AND slug='aphrodite' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Lyre' WHERE source_id='dd-3.0' AND slug='apollo' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Spear' WHERE source_id='dd-3.0' AND slug='ares' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-zeus','Zeus Divine Stat Block','101-103',
 'Zeus, Father of Gods and Mortals, is the divine-rank-19 greater deity and ruler of the Olympian pantheon.',
 '{"deitySlug":"zeus","pantheon":"olympian","sourceEdition":"3.0","rankBand":"greater","divineRank":19,"titles":["Father of Gods and Mortals"],"symbol":"Fist filled with lightning bolts","homePlane":"Olympus","alignment":"CG","classes":[{"class":"Barbarian","level":20},{"class":"Fighter","level":20},{"class":"Cleric","level":10}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+240 outsider + 20d12+240 barbarian + 20d10+270 fighter + 10d8+120 cleric","hitPoints":1550,"initiative":14,"speed":{"land":90,"fly":240,"maneuverability":"perfect"},"armorClass":{"total":86,"size":-1,"dexterity":10,"divine":19,"natural":32,"aegis":7,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"shortspear":"+93/+88/+83/+78 melee, Huge +5 shocking burst thundering shortspear","damage":"2d6+56/19-20/x3 plus 1d6 electricity; greater deity maximum 68","spellTouch":{"melee":83,"ranged":73},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":70,"ref":66,"will":65,"greaterDeityAlways20":true},"abilities":{"str":51,"dex":30,"con":34,"int":28,"wis":28,"cha":28},"specialAttacks":{"turnUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"54/+4 (4/-)","printedFireResistance":39,"spellResistance":51,"divineAura":{"radiusMiles":19,"dc":38},"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Annihilating Strike","Battlesense","Divine Rage","Call Creatures (celestial giant eagles)","Create Greater Object","Create Object","Creative Blood","Divine Battle Mastery","Divine Blast","Divine Creation","Divine Shield","Divine Splendor","Divine Weapon Focus (shortspear)","Divine Weapon Specialization (shortspear)","Energy Storm (lightning)","Extra Domain (Air)","Extra Domain (Nobility)","Extra Domain (Strength)","Mass Divine Blast","Shapechange","True Shapechange"],"uniqueAbilities":{"creativeBlood":"After Zeus suffers at least 20 damage from one attack, blood that strikes the ground becomes a random monster determined from dungeon level 1d4+10 and the DMG random-encounter table; blood that cannot reach ground does not transform."},"domainPowers":{"airTurningUsesPerDay":19,"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1,"nobilityInspireAlliesUsesPerDay":19,"nobilityMoraleBonus":2,"nobilityDurationRounds":9,"strengthFeatUsesPerDay":19,"strengthEnhancementBonus":10},"spellLikeAbilities":{"casterLevel":29,"chaosAndGoodCasterLevel":30,"saveDc":"38 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/8/7/6/6/5","clericBaseDc":"19 + spell level"},"divineRage":{"usesPerDay":19,"duration":"1 hour or until ended","armorClass":81,"hitPoints":1900,"attacks":"+98/+93/+88/+83 melee","fireResistance":49,"spellResistance":61,"saves":{"fort":75,"will":70},"strength":61,"constitution":44},"possessions":{"aegis":"+5 Huge heavy-fortification steel shield; frightful presence within 10 ft., Will DC 50; caster level 25; weight 30 lb."},"automaticActions":{"skills":"any skill Zeus possesses","freeActionDcMaximum":30,"maximumPerRound":20},"avatar":{"divineRank":9,"armorClass":66,"attacks":"shortspear +83/+78/+73/+68, 2d6+46 plus 1d6 electricity/x3","spellTouch":{"melee":73,"ranged":63},"damageReduction":"44/+4","fireResistance":29,"spellResistance":41,"divineAura":{"radiusFeet":900,"dc":28},"saves":{"fort":60,"ref":56,"will":55},"salientDivineAbilities":["Alter Size","Annihilating Strike","Creative Blood","Divine Blast","Divine Rage","Divine Shield","Divine Weapon Focus (spear)","Divine Weapon Specialization (spear)","Extra Domain (Air)","Extra Domain (Nobility)","Extra Domain (Strength)"],"spellLikeCasterLevel":19,"spellLikeSaveDc":"28 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"30/epic","fireResistance":24,"additionalOutsiderSkillPoints":true,"battlesense":"Replaces uncanny dodge and improved uncanny dodge.","divineRage":"Use revised Divine Rage: one extra attack at full attack bonus on a full attack rather than an extra partial action.","defunctFeat":"Improved Sunder is obsolete in the update and must use the revised Improved Sunder treatment."}}'),

('dd-statblock-aphrodite','Aphrodite Divine Stat Block','103-105',
 'Aphrodite is the divine-rank-14 intermediate Olympian deity of love and beauty.',
 '{"deitySlug":"aphrodite","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":14,"symbol":"Seashell","homePlane":"Olympus","alignment":"CG","classes":[{"class":"Bard","level":20},{"class":"Cleric","level":10},{"class":"Sorcerer","level":10}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+140 outsider + 20d6+140 bard + 10d8+70 cleric + 10d4+70 sorcerer","hitPoints":820,"initiative":10,"speed":{"land":80},"armorClass":{"total":78,"size":-1,"dexterity":10,"divine":14,"natural":27,"deflection":18},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"wave":"+63 ranged touch","waveDamage":"1d10","dagger":"+69/+64/+59/+54 melee or +68 ranged, Small +5 chaotic dancing dagger","daggerDamage":"1d6+16/19-20","spellTouch":{"melee":65,"ranged":63}},"saves":{"fort":53,"ref":58,"will":53,"intermediateDeityChecksAlways20":true},"abilities":{"str":32,"dex":30,"con":24,"int":30,"wis":24,"cha":47},"specialAttacks":{"turnUndeadPerDay":21},"specialQualities":{"printedDamageReduction":"49/+4","printedFireResistance":34,"spellResistance":46,"divineAura":{"radiusFeet":1400,"dc":42},"bardicKnowledge":30,"bardicMusicPerDay":20,"bardicMusicRangeMiles":14,"familiar":"butterflies","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Avatar","Create Greater Object","Create Object","Curse of Madness","Divine Bard","Divine Blessing (Charisma)","Divine Dodge","Divine Inspiration (any emotion)","Divine Shield","Divine Skill Focus (Perform)","Divine Spell Focus (Enchantment)","Empowered Inspiration (love and desire)","Shapechange"],"uniqueAbilities":{"curseOfMadness":"A mortal who angers Aphrodite can be afflicted by a permanent insanity effect with no save; for a male target she may instead impose impotence.","empoweredInspiration":"Love/desire inspiration can affect deities of any rank; DC 56. Athena, Hestia, and Artemis are noted as immune."},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"charismaIncreaseUsesPerDay":14,"charismaIncrease":4,"charismaIncreaseDuration":"1 minute","goodSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":24,"chaosAndGoodCasterLevel":25,"saveDc":"42 + spell level"},"spellcasting":{"bardSpellsKnownPerDay":"4/9/9/8/8/8/8","bardBaseDc":"28 + spell level; 42 + spell level for enchantments","clericSpellsPerDay":"6/7/7/6/5/4","clericBaseDc":"17 + spell level; 31 + spell level for enchantments","sorcererSpellsKnownPerDay":"6/11/11/10/9/7","sorcererBaseDc":"28 + spell level; 42 + spell level for enchantments"},"automaticActions":{"skills":"Charisma-related skills in which she has ranks or that are usable untrained","freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":64,"attacks":"wave +56 ranged touch (1d10); dagger +62/+57/+52/+47 melee or +61 ranged","spellTouch":{"melee":56,"ranged":58},"printedDamageReduction":"42/+1","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":35},"saves":{"fort":46,"ref":51,"will":46},"perform":92,"salientDivineAbilities":["Alter Form","Alter Size","Area Divine Shield","Create Greater Object","Create Object","Divine Bard","Divine Blessing (Charisma)","Divine Shield","Divine Skill Focus (Perform)"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"35 + spell level","sourceNotes":["The printed avatar block says DR 42/+1, inconsistent with the book''s normal divine DR progression.","The printed avatar spell note refers to wizard spells even though Aphrodite has sorcerer levels; the source wording is retained as an error note rather than silently normalized."]},"revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"25/epic","fireResistance":19,"additionalOutsiderSkillPoints":true,"divineBard":"Apply revised Divine Bard bonuses.","divineSpellFocus":"Use one-half divine rank rather than full divine rank for the save-DC increase.","skillFocus":"Use revised Skill Focus bonus."}}'),

('dd-statblock-apollo','Apollo Divine Stat Block','105-107',
 'Apollo is the divine-rank-15 intermediate Olympian deity of light, prophecy, music, and healing.',
 '{"deitySlug":"apollo","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Musician of the Gods","The Archer God","The Farshooter","The Healer","The God of Light","The God of Truth"],"symbol":"Lyre","homePlane":"Olympus","alignment":"CG","classes":[{"class":"Fighter","level":9},{"class":"Bard","level":20},{"class":"Wizard","level":10},{"class":"Cleric","level":10}],"creature":{"type":"Outsider","subtypes":["Chaotic","Good"],"size":"Large","hitDice":"20d8+140 outsider + 9d10+63 fighter + 20d6+140 bard + 10d4+70 wizard + 10d8+70 cleric","hitPoints":973,"initiative":15,"speed":{"land":80},"armorClass":{"total":75,"size":-1,"dexterity":11,"divine":15,"natural":28,"deflection":12},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"bow":"+85/+85/+80/+75/+70 ranged, Huge +5 mighty speed disruption holy composite longbow (+7 Str) with +5 arrows","bowDamage":"1d10+19/19-20/x3","unarmed":"+66/+61/+56/+51 melee","unarmedDamage":"1d4+7","spellTouch":{"melee":66,"ranged":70}},"saves":{"fort":58,"ref":63,"will":61,"intermediateDeityChecksAlways20":true},"abilities":{"str":24,"dex":33,"con":24,"int":40,"wis":30,"cha":34},"specialAttacks":{"turnUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"spellResistance":67,"divineAura":{"radiusFeet":1500,"dc":37},"bardicKnowledge":35,"bardicMusicPerDay":28,"bardicMusicRangeMiles":15,"familiar":"hawk","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Arcane Mastery","Avatar","Divine Archery","Divine Bard","Divine Blast","Divine Shield","Divine Weapon Focus (composite longbow)","Extra Domain (Healing)","Extra Domain (Knowledge)","Gift of Life","Instant Counterspell","Irresistible Performance","Power of Truth","Spontaneous Wizard Spells"],"domainPowers":{"goodSpellsCasterLevelBonus":1,"healingSpellsCasterLevelBonus":1,"divinationSpellsCasterLevelBonus":1,"magicDomainUseItemsAsWizardLevel":15,"greaterTurningUsesPerDay":15},"spellLikeAbilities":{"casterLevel":25,"goodHealingDivinationCasterLevel":26,"saveDc":"38 + spell level"},"spellcasting":{"bardSpellsKnownPerDay":"4/7/7/7/7/6/6","bardBaseDc":"22 + spell level; 26 + spell level for enchantments and illusions","clericSpellsPerDay":"6/8/8/6/6/5","clericBaseDc":"20 + spell level; 24 + spell level for enchantments and illusions","wizardSpellsPerDay":"4/8/8/7/6/5","wizardBaseDc":"25 + spell level; 29 + spell level for enchantments and illusions"},"possessions":{"arrows":"+5 arrows; living targets struck save Fort DC 23 or contract Apollo plague, incubation 1 day, 1d4 Con and 1d4 Dex damage; caster level 20; 20 arrows weigh 3 lb."},"automaticActions":{"skills":["Craft (musical instrument)","Knowledge (arcana)","Knowledge (geography)","Knowledge (history)","Knowledge (nature)","Knowledge (nobility and royalty)","Knowledge (religion)","Knowledge (the planes)","Profession (herbalist)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":59,"attacks":"bow +77/+77/+72/+67/+62 or unarmed +58/+53/+48/+43","spellTouch":{"melee":58,"ranged":62},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":29},"saves":{"fort":50,"ref":55,"will":53},"salientDivineAbilities":["Alter Size","Arcane Mastery","Divine Archery","Divine Shield","Divine Weapon Focus (composite longbow)","Extra Domain (Healing)","Extra Domain (Knowledge)","Power of Truth","Spontaneous Wizard Spells"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"30 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"divineBard":"Apply revised Divine Bard bonuses.","spellFocus":"Recalculate focused-school save DCs under revised Spell Focus and Greater Spell Focus.","defunctSkills":["Alchemy becomes Craft (alchemy)","Scry ranks are reassigned under the official update"]}}'),

('dd-statblock-ares','Ares Divine Stat Block','107-108',
 'Ares is the divine-rank-15 intermediate Olympian deity of war, killing, and strife.',
 '{"deitySlug":"ares","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Ruthless God","He Who Delights in Battle"],"symbol":"Spear","homePlane":"Olympus","alignment":"CE","sourceIdentityNote":"Table 4-1 lists favored weapon Shortspear; the individual Ares entry lists Halfspear. Both printed values are retained.","classes":[{"class":"Cleric","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","subtypes":["Chaotic","Evil"],"size":"Large","hitDice":"20d8+220 outsider + 20d8+220 cleric + 20d10+220 fighter","hitPoints":1180,"initiative":"+12, always first","speed":{"land":80},"armorClass":{"total":86,"size":-1,"dexterity":8,"divine":15,"natural":28,"armor":10,"shield":7,"deflection":9},"armorNotes":["+5 heavy fortification breastplate","+5 large steel shield"],"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"shortspear":"+84/+79/+74/+69 melee, +5 chaotic unholy ghost touch shortspear","damage":"1d8+41/19-20/x3","spellTouch":{"melee":74,"ranged":63}},"saves":{"fort":58,"ref":55,"will":54,"intermediateDeityChecksAlways20":true},"abilities":{"str":48,"dex":26,"con":32,"int":25,"wis":25,"cha":29},"specialAttacks":{"rebukeUndeadPerDay":12},"specialQualities":{"printedDamageReduction":"40/+4","printedFireResistance":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":34},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Reality","Alter Size","Annihilating Strike","Avatar","Battlesense","Divine Armor Mastery","Divine Battle Mastery","Divine Blast","Divine Inspiration (rage)","Divine Shield","Divine Storm","Divine Weapon Focus (shortspear)","Divine Weapon Specialization (shortspear)","Extra Domain (Chaos)","Frightful Presence","Mass Divine Blast","Supreme Initiative","Wound Enemy"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"smiteUsesPerDay":15,"smiteAttackBonus":20,"smiteDamageBonus":20,"evilSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":25,"chaosAndEvilCasterLevel":26,"saveDc":"34 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"17 + spell level"},"automaticActions":{"skills":["Craft (armorsmithing)","Craft (metalworking)","Craft (weaponsmithing)","Knowledge (nobility and royalty)"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":70,"attacks":"shortspear +77/+73/+67/+63, 1d8+33/x3","spellTouch":{"melee":66,"ranged":55},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":26},"saves":{"fort":50,"ref":47,"will":46},"salientDivineAbilities":["Alter Size","Battlesense","Divine Battle Mastery","Divine Blast","Divine Shield","Divine Weapon Focus (shortspear)","Divine Weapon Specialization (shortspear)","Extra Domain (Chaos)","Wound Enemy"],"spellLikeCasterLevel":17,"spellLikeSaveDc":"26 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","evil"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"battlesense":"Replaces uncanny dodge and improved uncanny dodge.","defunctFeat":"Improved Sunder is obsolete in the update and must use the revised Improved Sunder treatment."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-olympian-pantheon',NULL,
  '["deities-and-demigods","olympian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
